describe('Delete Record Confirmation Modal', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should display confirmation modal when delete button is clicked', () => {
    // Intercept the delete API call
    cy.intercept('DELETE /api/records/*').as('deleteRecord');

    // Find and click the delete button for a record
    cy.get('[data-testid="delete-button-record-1"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="modal-title"]').should('contain', 'Confirm Deletion');
    cy.get('[data-testid="modal-message"]').should('contain', 'Are you sure you want to delete this record?');

    // Verify confirm and cancel buttons are visible
    cy.get('[data-testid="confirm-delete-button"]').should('be.visible');
    cy.get('[data-testid="cancel-delete-button"]').should('be.visible');

    // Verify modal has focus
    cy.get('[data-testid="confirmation-modal"]').should('have.focus');
  });

  it('should close modal when cancel button is clicked and not delete record', () => {
    // Intercept the delete API call
    cy.intercept('DELETE /api/records/*').as('deleteRecord');

    // Click delete button
    cy.get('[data-testid="delete-button-record-2"]').click();

    // Verify modal appears
    cy.get('[data-testid="confirmation-modal"]').should('be.visible');

    // Click cancel button
    cy.get('[data-testid="cancel-delete-button"]').click();

    // Verify modal closes
    cy.get('[data-testid="confirmation-modal"]').should('not.exist');

    // Verify record still exists
    cy.get('[data-testid="record-row-2"]').should('be.visible');
  });
});
